effect.shader:
vec4 sampleTex(sampler2D t, vec2 uv){ return texture2DCv(t, uv); }
float hash(float n){ return fract(sin(n)*43758.5453123); }
float noise1(float x){
float i = floor(x), f = fract(x);
float u = f*f*(3.0-2.0*f);
return mix(hash(i+seed), hash(i+1.0+seed), u);
}
float fbm(float x, float oct, float rough){
float a = 1.0, f = 1.0, sum = 0.0, norm = 0.0;
for(int i=0;i<8;i++){
if(float(i) >= oct) break;
sum += noise1(x*f) * a;
norm += a;
a *= clamp(rough, 0.0, 1.0);
f *= 2.0;
}
return (norm>0.0)? sum/norm : 0.0;
}
mat2 rot2(float a){ float s=sin(a), c=cos(a); return mat2(c,-s,s,c); }
vec2 mirror(vec2 uv){ return abs(fract(uv*0.5+0.5)*2.0-1.0); }
void main(){
vec2 uv = acScreenNorm;
float t = acTime * frequency;
float oct = clamp(octaves, 1.0, 6.0);
float nX = fbm(t + 37.17, oct, roughness) * 2.0 - 1.0;
float nY = fbm(t + 91.73, oct, roughness) * 2.0 - 1.0;
float nR = fbm(t + 153.11, oct, roughness) * 2.0 - 1.0;
float nS = fbm(t + 241.57, oct, roughness) * 2.0 - 1.0;
vec2 posPx = vec2(ampPosX*nX, ampPosY*nY) * strength;
float rotDeg = ampRot * nR * strength;
float scl = 1.0 + ampScale * nS * strength;
vec2 texSize = inputImg.size;
vec2 posUV = posPx / max(texSize, vec2(1.0));
vec2 pivot = vec2(pivotX, pivotY);
float autoS = 1.0 + expand;
float rot = radians(rotDeg);
vec2 rel = uv - pivot;
rel -= posUV;
rel = rot2(-rot) * rel;
rel /= max(scl*autoS, 1e-6);
vec2 srcUV = pivot + rel;
vec4 col;
if(mirrorEdges){
col = sampleTex(inputImg.texture, mirror(srcUV));
} else {
if(any(lessThan(srcUV, vec2(0.0))) || any(greaterThan(srcUV, vec2(1.0)))){
col = vec4(0.0);
} else {
col = sampleTex(inputImg.texture, srcUV);
}
}
gl_FragColor = col;
}
